func TestPageRangesPreserveEverySurvivingRowWithTombstones(emonT *testing.T) {
	var rows *port.Cells = port.NewCells()
	var r int32 = 0
	var p int32 = 0
	var first int32 = 0
	var end int32 = 0
	for r < 140 {
		p = 1 + (r / 7)
		if (r % 3) == 0 {
			p = -7
		}
		if (r % 5) == 0 {
			p = 0
		}
		port.CellsPush(rows, p)
		port.CellsPush(rows, r)
		port.CellsPush(rows, 0)
		r += 1
	}
	p = 1
	for p <= 22 {
		first = pagebounds.PbFirst(rows, 3, p)
		end = pagebounds.PbAfter(rows, 3, p)
		port.AssertThat(emonT, (first >= 0) && ((first <= end) && (end <= 140)), "valid range")
		r = 0
		for r < 140 {
			if port.CellsAt(rows, r*3) == p {
				port.AssertThat(emonT, (r >= first) && (r < end), "every old-scan hit is inside the range in the same order")
			}
			r += 1
		}
		p += 1
	}
}

func TestZeroBasedTracePagesAndAbsentPages(emonT *testing.T) {
	var rows *port.Cells = port.NewCells()
	port.CellsPush(rows, 0)
	port.CellsPush(rows, 0)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 2)
	port.AssertEq(emonT, pagebounds.PbFirst(rows, 1, 0), 0, "page zero starts at zero")
	port.AssertEq(emonT, pagebounds.PbAfter(rows, 1, 0), 2, "page zero ends before positive pages")
	port.AssertEq(emonT, pagebounds.PbFirst(rows, 1, 1), 2, "absent page has an empty range")
	port.AssertEq(emonT, pagebounds.PbAfter(rows, 1, 1), 2, "absent page has an empty range")
	port.AssertEq(emonT, pagebounds.PbAfter(rows, 1, 2), 4, "last page includes its last row")
}

func TestAppendedColumnPiecesHaveASeparatePageOrderedRun(emonT *testing.T) {
	var rows *port.Cells = port.NewCells()
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 3)
	port.CellsPush(rows, 3)
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 3)
	port.AssertEq(emonT, pagebounds.PbFirstSpan(rows, 1, 3, 0, 6), 4, "original page three begins before the appended pieces")
	port.AssertEq(emonT, pagebounds.PbFirstSpan(rows, 1, 4, 0, 6), 6, "original page three ends at the immutable boundary")
	port.AssertEq(emonT, pagebounds.PbFirstSpan(rows, 1, 3, 6, 10), 9, "appended page three follows earlier pages' pieces")
	port.AssertEq(emonT, pagebounds.PbFirstSpan(rows, 1, 4, 6, 10), 10, "all appended pieces are retained")
}

func TestRangeIndexKeepsUnorderedFixturesAndDeletedRows(emonT *testing.T) {
	var rows *port.Cells = port.NewCells()
	var ix *port.Cells = port.NewCells()
	port.CellsPush(rows, 2)
	port.CellsPush(rows, -7)
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 0)
	port.CellsPush(rows, 3)
	pagebounds.PbBuildRanges(rows, 1, 0, 6, 4, ix)
	port.AssertEq(emonT, port.CellsAt(ix, 2), 2, "page one's first row")
	port.AssertEq(emonT, port.CellsAt(ix, 3), 3, "page one's end")
	port.AssertEq(emonT, port.CellsAt(ix, 4), 0, "page two includes its earlier row")
	port.AssertEq(emonT, port.CellsAt(ix, 5), 4, "page two includes its later row")
	port.AssertEq(emonT, port.CellsAt(ix, 8), 6, "empty page begins at the end")
	port.AssertEq(emonT, port.CellsAt(ix, 9), 6, "empty page stays empty")
}
